public class RunRecap {
 public int version=1,number;public string profile,result,route,endingRoom,killedBy,weapon,aspect,importedAt,checkpointAt;public bool cleared;
 public double? seconds,totalSeconds,damageTaken,damageDealt,fear,rooms,grasp,aspectRank;
 public RecapItem[] items=new RecapItem[0];public string[] keepsakes=new string[0];public SavedChoice[] choices=new SavedChoice[0];
 public int presentationVersion;public string resultEvidence,victoryImage,victoryAt;public double? victorySeconds;public DamageRow[] inflicted=new DamageRow[0],suffered=new DamageRow[0];public string damageEvidence;
